//! j8binding: Rust ⇄ JS bindings (the counterpart of V8's FunctionTemplate / ObjectTemplate).
//!
//! - [`FromJs`] / [`IntoJs`]: conversion of arguments and return values (numbers, booleans, strings,
//!   `Option`, `Vec`, objects, `Result`, ...)
//! - [`Class`] / [`Object`]: export a Rust type as a JS class / plain object; usually not written by hand
//!   but generated by `#[j8::class]` / `#[j8::object]` / `#[j8::function]` from the facade crate `j8`
//! - Host objects: a JS object holding a Rust value ([`ObjectKind::Host`]), taken out in methods as
//!   `&self` / `&mut self`
//!
//! ```ignore
//! struct Counter { n: f64 }
//!
//! #[j8::class]
//! impl Counter {
//!     #[js(constructor)]
//!     fn new(start: Option<f64>) -> Self { Self { n: start.unwrap_or(0.0) } }
//!     fn inc(&mut self, by: f64) -> f64 { self.n += by; self.n }
//!     #[js(getter)]
//!     fn value(&self) -> f64 { self.n }
//!     fn zero() -> f64 { 0.0 }            // no self: static method
//! }
//!
//! let handle = Counter::install(&mut agent, global)?;   // global `Counter`
//! ```
extern crate alloc;

mod class;
mod convert;
mod module;

pub use class::{Class, ClassHandle, Member, Object};
pub use convert::{FromJs, IntoJs, Rest, This};
pub use module::{Install, Module, NATIVE};

#[doc(hidden)]
pub use j8framework as frame;
#[doc(hidden)]
pub use class::Glue;
